    const existing=new Set(x.projects.map(p=>p.id));
    seed.projects.forEach(p=>{if(!existing.has(p.id))x.projects.push(clone(p))});
    x.masters=x.masters||{workstreams:[],tasks:[],units:[],milestones:[]};
