function load(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY));if(x&&x.projects&&x.masters)return migrateState(x)}catch{} const x=clone(seed);x.dashboard={sections:[],groupBy:'custom',subGroupBy:'none',timelineGroup:'subtask',phasingViewV1:true,savedViews:[],collapsedProjects:[],collapsedTasks:[],collapsedSubTasks:[],expandedMilestones:[]};x.settings={...(x.settings||{}),schemaVersion:4,teamSync:false,serverRevision:0};return migrateState(x)}
function save(){state.settings=state.settings||{};state.settings.serverRevision=serverRevision;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(state.settings.teamSync)queueTeamSync();}
function teamToken(){return sessionStorage.getItem(TOKEN_KEY)||''}
