function updateSyncBadge(mode='local',text='Local'){const el=document.getElementById('syncStatus');if(!el)return;el.className='sync-status '+mode;el.textContent=text}
function queueTeamSync(){if(isSyncing)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncServer(true),700)}
async function checkTeamSession(){try{const r=await fetch('/api/session',{headers:teamHeaders()});const x=await r.json();teamRole=x.role||'none';if(state.settings?.teamSync)updateSyncBadge(teamRole==='viewer'?'viewer':'synced',teamRole==='none'?'Auth needed':`Team · ${teamRole}`);else updateSyncBadge('local','Local')}catch{teamRole='local';updateSyncBadge('local','Local')}}
async function loadServerState({silent=false}={}){try{updateSyncBadge('syncing','Loading…');const r=await fetch('/api/state',{headers:teamHeaders()});const x=await r.json();if(!r.ok)throw new Error(x.error||'Load failed');teamRole=x.role||teamRole;serverRevision=Number(x.revision||0);if(x.state&&x.state.projects){state=migrateState(x.state);state.settings=state.settings||{};state.settings.serverRevision=serverRevision;state.settings.teamSync=true;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));dashboardSectionField=state.dashboard?.groupBy||'custom';dashboardSubSectionField=state.dashboard?.subGroupBy||'none';dashboardTimelineGroup=state.dashboard?.timelineGroup||'subtask';dashboardTimeMode=state.dashboard?.timeMode||'Week';dashboardZoom=Number(state.dashboard?.zoom||100);render()}updateSyncBadge(teamRole==='viewer'?'viewer':'synced',`Synced r${serverRevision}`);return true}catch(e){updateSyncBadge('conflict','Sync error');if(!silent)alert('Team sync: '+e.message);return false}}
async function syncServer(silent=false){if(isSyncing)return;try{isSyncing=true;updateSyncBadge('syncing','Syncing…');const payload={state,baseRevision:serverRevision,user:teamUser()};const res=await fetch('/api/state',{method:'PUT',headers:teamHeaders(true),body:JSON.stringify(payload)});const x=await res.json();if(res.status===409){updateSyncBadge('conflict',`Conflict r${x.currentRevision}`);if(!silent&&confirm('A newer team revision exists. Load the latest team version now?'))await loadServerState();return}if(!res.ok)throw new Error(x.error||'Save failed');serverRevision=Number(x.revision||serverRevision);state.settings=state.settings||{};state.settings.serverRevision=serverRevision;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));updateSyncBadge('synced',`Synced r${serverRevision}`);if(!silent)alert(`Team state saved · revision ${serverRevision}`)}catch(e){updateSyncBadge('conflict','Sync error');if(!silent)alert('Team sync failed: '+e.message)}finally{isSyncing=false}}
function setTeamSync(enabled){state.settings=state.settings||{};state.settings.teamSync=!!enabled;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(enabled)loadServerState();else{updateSyncBadge('local','Local');render()}}
function setTeamIdentity(){const name=(document.getElementById('teamUserName')?.value||'').trim()||'User';const token=(document.getElementById('teamToken')?.value||'').trim();localStorage.setItem(USER_KEY,name);if(token)sessionStorage.setItem(TOKEN_KEY,token);else sessionStorage.removeItem(TOKEN_KEY);checkTeamSession().then(()=>openTeamCenter())}
async function openTeamCenter(){let history=[];try{const r=await fetch('/api/history?limit=30',{headers:teamHeaders()});const x=await r.json();if(r.ok)history=x.history||[]}catch{}const role=teamRole||'local';showModal(`<div class="modal-head"><h2>Team Sync & Governance <span class="v2-version">v${APP_VERSION}</span></h2><button class="btn sm" onclick="closeModal()">×</button></div><div class="modal-body"><div class="governance-grid"><div class="governance-box"><div class="section-title">Team identity</div><div class="ff"><label>User / editor name</label><input id="teamUserName" value="${esc(teamUser())}"></div><div class="ff" style="margin-top:8px"><label>Access token (optional server security)</label><input id="teamToken" type="password" placeholder="Configured on Render" value="${esc(teamToken())}"></div><button class="btn" style="margin-top:9px" onclick="setTeamIdentity()">Apply</button><div class="small" style="margin-top:7px">Role: <span class="role-badge">${esc(role)}</span></div></div><div class="governance-box"><div class="section-title">Shared team mode</div><label class="dashboard-flag show"><input type="checkbox" ${state.settings?.teamSync?'checked':''} onchange="setTeamSync(this.checked)"><span>Auto-sync team state</span></label><div class="small" style="margin-top:8px">Optimistic revision control prevents silent overwrites. Local mode remains available for offline work.</div><div style="display:flex;gap:6px;margin-top:10px"><button class="btn sm" onclick="loadServerState()">Pull latest</button><button class="btn sm primary" onclick="syncServer()">Push now</button></div></div><div class="governance-box"><div class="section-title">Control Tower model</div><div class="small">Schema v4 · Project → Workstream → Task → Phase/Sub-Task → Activity/Milestone</div><div class="small" style="margin-top:6px">Progress: reported or weighted calculated</div><div class="small" style="margin-top:6px">Primary live milestone supported</div><div class="small" style="margin-top:6px">Revision: ${serverRevision||0}</div></div></div><div class="section-title" style="margin-top:18px">Audit history</div><div class="history-list">${history.map(h=>`<div class="history-row"><b>r${h.revision}</b><div><div>${esc(h.action||'save')}</div><div class="small">${esc(h.user||'unknown')} · ${new Date(h.at).toLocaleString()}</div></div>${role==='admin'&&Number(h.revision)<Number(serverRevision)&&String(h.action||'').startsWith('restore')===false?`<button class="btn sm" onclick="restoreTeamRevision(${h.revision})">Restore</button>`:''}</div>`).join('')||'<div class="empty">No server history or not connected.</div>'}</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Close</button></div>`)}
async function restoreTeamRevision(rev){if(!confirm(`Restore team data to revision ${rev}? Current state will be preserved as a new revision.`))return;try{const r=await fetch('/api/restore/'+rev,{method:'POST',headers:teamHeaders()});const x=await r.json();if(!r.ok)throw new Error(x.error||'Restore failed');serverRevision=Number(x.revision||serverRevision);await loadServerState();openTeamCenter()}catch(e){alert(e.message)}}
