function statusPill(s){const cls=s==='InProgress'?'InProgress':s;return `<span class="pill st-${cls}">${STATUS_LABEL[s]||s}</span>`}
function dateVal(s){return s?new Date(s+'T12:00:00').getTime():0}
function days(a,b){return Math.round((dateVal(b)-dateVal(a))/86400000)}
function calculatedProgress(p){const a=p.activities||[];if(!a.length)return 0;const score={Completed:100,InProgress:50,AtRisk:40,Delayed:35,OnHold:25,Upcoming:0};let weighted=0,total=0;for(const x of a){const w=Math.max(.1,Number(x.weight||1));weighted+=(score[x.status]??0)*w;total+=w}return total?Math.round(weighted/total):0}
function progress(p){if(p.progressMode==='reported'&&Number.isFinite(Number(p.reportedProgress)))return Math.max(0,Math.min(100,Math.round(Number(p.reportedProgress))));return calculatedProgress(p)}
function projectStatus(p){const a=p.activities||[];if(!a.length)return'Upcoming';if(a.every(x=>x.status==='Completed'))return'Completed';if(a.some(x=>x.status==='Delayed'))return'Delayed';if(a.some(x=>x.status==='AtRisk'))return'AtRisk';if(a.some(x=>x.status==='OnHold'))return'OnHold';if(a.some(x=>x.status==='InProgress'))return'OnTrack';return'Upcoming'}
function overdueSteps(p){const today=dateVal(dateOffset(0));return (p.activities||[]).flatMap(a=>(a.nextSteps||[]).map(s=>({a,s}))).filter(x=>x.s.status!=='Completed'&&dateVal(x.s.due)<today)}
function upcomingActivities(p,n=14){const t=dateVal(dateOffset(0)),end=t+n*86400000;return (p.activities||[]).filter(a=>dateVal(a.plannedEnd)>=t&&dateVal(a.plannedEnd)<=end&&a.status!=='Completed').sort((a,b)=>dateVal(a.plannedEnd)-dateVal(b.plannedEnd))}
