function startOfWeekMs(msv){const d=new Date(msv);d.setHours(12,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.getTime()}
function isoWeek(d){const x=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));x.setUTCDate(x.getUTCDate()+4-(x.getUTCDay()||7));const y=new Date(Date.UTC(x.getUTCFullYear(),0,1));return Math.ceil((((x-y)/86400000)+1)/7)}
function dashStatus(p){const s=projectStatus(p);return s==='Completed'?'Completed':s==='AtRisk'?'At Risk':s==='OnTrack'?'On Track':s==='OnHold'?'On Hold':s}
function projectLiveDate(p){const acts=(p.activities||[]).filter(a=>a.plannedStart||a.plannedEnd);const primary=acts.filter(a=>a.isPrimaryLive===true);if(primary.length){const a=primary.slice().sort((a,b)=>dateVal(a.plannedStart||a.plannedEnd)-dateVal(b.plannedStart||b.plannedEnd)).slice(-1)[0];return a.plannedStart||a.plannedEnd||''}const masterLive=acts.filter(a=>ms(a.key).isLiveDefault===true);if(masterLive.length){const a=masterLive.slice().sort((a,b)=>dateVal(a.plannedStart||a.plannedEnd)-dateVal(b.plannedStart||b.plannedEnd)).slice(-1)[0];return a.plannedStart||a.plannedEnd||''}const live=acts.filter(a=>{const t=((a.key||'')+' '+(a.label||'')+' '+(ms(a.key).name||'')).toLowerCase();return t.includes('live')||t.includes('implementation')||t.includes('relaunch')||t.trim().startsWith('go')});const pick=(live.length?live:acts).slice().sort((a,b)=>dateVal(a.plannedStart||a.plannedEnd)-dateVal(b.plannedStart||b.plannedEnd)).slice(-1)[0];return pick?.plannedStart||pick?.plannedEnd||p.plannedEnd||''}
function projectLiveWeek(p){const d=projectLiveDate(p);if(!d)return'-';const dt=new Date(dateVal(d));return 'W'+String(isoWeek(dt)).padStart(2,'0')}
function isoWeekYear(d){const x=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));x.setUTCDate(x.getUTCDate()+4-(x.getUTCDay()||7));return x.getUTCFullYear()}
function projectLiveActivities(p){const acts=(p.activities||[]).filter(a=>a.plannedStart||a.plannedEnd);return acts.filter(a=>{const master=ms(a.key),t=((a.key||'')+' '+(a.label||'')+' '+(master.name||'')).toLowerCase();return a.isPrimaryLive===true||master.isLiveDefault===true||/\blive\b|implementation|relaunch|\bgo\b/.test(t)}).slice().sort((a,b)=>dateVal(a.plannedStart||a.plannedEnd)-dateVal(b.plannedStart||b.plannedEnd))}
function projectLiveWeekEntries(p){const acts=projectLiveActivities(p),seen=new Map();for(const a of acts){const date=a.plannedStart||a.plannedEnd;if(!date)continue;const dt=new Date(dateVal(date)),week=isoWeek(dt),year=isoWeekYear(dt),key=`${year}-W${String(week).padStart(2,'0')}`;if(!seen.has(key))seen.set(key,{week,year,date,items:[]});seen.get(key).items.push(a)}if(!seen.size){const date=projectLiveDate(p);if(date){const dt=new Date(dateVal(date)),week=isoWeek(dt),year=isoWeekYear(dt);seen.set(`${year}-W${String(week).padStart(2,'0')}`,{week,year,date,items:[]})}}return [...seen.values()].sort((a,b)=>dateVal(a.date)-dateVal(b.date))}
function projectLiveWeeksText(p){const entries=projectLiveWeekEntries(p);if(!entries.length)return'-';const multiYear=new Set(entries.map(x=>x.year)).size>1;return entries.map(x=>`W${String(x.week).padStart(2,'0')}${multiYear?'/'+String(x.year).slice(-2):''}`).join(' · ')}
function projectLiveWeeksTitle(p){const entries=projectLiveWeekEntries(p);return entries.map(x=>{const names=x.items.length?[...new Set(x.items.map(a=>a.key||a.label).filter(Boolean))].join(', '):'Live';return `W${String(x.week).padStart(2,'0')} · ${x.date} · ${names}`}).join('\n')||projectLiveDate(p)||''}
function projectPic(p){const pics=[...new Set((p.activities||[]).flatMap(a=>(a.responsibilities||[]).map(r=>r.pic).filter(Boolean)))];return pics.slice(0,2).join(' / ')||p.owner||'—'}
function sectionName(id){return state.dashboard?.sections?.find(s=>s.id===id)?.name||'Unassigned'}
