function dashboardFilteredProjects(){let ps=state.projects.filter(p=>p.showOnDashboard!==false);const f=dashboardFilter;if(f.search){const q=f.search.toLowerCase();ps=ps.filter(p=>[p.code,p.name,p.summary,p.eventType,p.owner,p.format,p.division,p.department].some(v=>String(v||'').toLowerCase().includes(q)))}if(f.eventType!=='All')ps=ps.filter(p=>p.eventType===f.eventType);if(f.status!=='All')ps=ps.filter(p=>dashStatus(p)===f.status);if(f.owner!=='All')ps=ps.filter(p=>p.owner===f.owner);if(f.section!=='All')ps=ps.filter(p=>dashboardGroupKey(p)===f.section);if(f.subSection!=='All'&&dashboardSubSectionField!=='none')ps=ps.filter(p=>dashboardSubGroupKey(p)===f.subSection);return ps}
function dashboardSortMeta(){const s=dashboardSort;if(s==='eventTypeDesc')return['eventType','desc'];if(s==='eventTypeAsc'||s==='eventType')return['eventType','asc'];if(s==='formatDesc')return['format','desc'];if(s==='formatAsc'||s==='format')return['format','asc'];if(s==='projectDesc')return['project','desc'];if(s==='projectAsc')return['project','asc'];if(s==='liveDesc')return['live','desc'];if(s==='liveAsc')return['live','asc'];if(s==='statusDesc')return['status','desc'];if(s==='statusAsc'||s==='status')return['status','asc'];if(s==='planStartDesc')return['planStart','desc'];if(s==='planStartAsc'||s==='planStart')return['planStart','asc'];return['live','asc']}
function compareDashboard(a,b){const [key,dir]=dashboardSortMeta();let c=0;if(key==='live')c=dateVal(projectLiveDate(a))-dateVal(projectLiveDate(b));else if(key==='project')c=String(a.name||'').localeCompare(String(b.name||''));else if(key==='eventType')c=String(a.eventType||'').localeCompare(String(b.eventType||''));else if(key==='format')c=String(a.format||'').localeCompare(String(b.format||''));else if(key==='status')c=dashStatus(a).localeCompare(dashStatus(b));else if(key==='planStart')c=dateVal(a.plannedStart)-dateVal(b.plannedStart);if(c===0)c=String(a.name||'').localeCompare(String(b.name||''));return dir==='desc'?-c:c}
