function initDashboardPan(){const wrap=document.querySelector('.portfolio-gantt-wrap');if(!wrap)return;wrap.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;const panArea=e.target.closest('.portfolio-time-head,.portfolio-track,.portfolio-child-track,.portfolio-section-time,.portfolio-subsection-time');if(!panArea||e.target.closest('button,input,select,textarea,a,.project-link,.portfolio-milestone,.portfolio-ms-label,.collapse-toggle,.dashboard-milestone-panel'))return;const startX=e.clientX,startY=e.clientY,startLeft=wrap.scrollLeft,startTop=window.scrollY;let moved=false;e.preventDefault();wrap.classList.add('pan-holding');wrap.setPointerCapture?.(e.pointerId);const move=ev=>{const dx=ev.clientX-startX,dy=ev.clientY-startY;if(!moved&&Math.hypot(dx,dy)>4)moved=true;if(!moved)return;wrap.classList.add('is-panning');wrap.scrollLeft=Math.max(0,startLeft-dx);window.scrollTo(window.scrollX,Math.max(0,startTop-dy))};const done=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',done);window.removeEventListener('pointercancel',done);wrap.classList.remove('pan-holding','is-panning');wrap.releasePointerCapture?.(e.pointerId)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',done,{once:true});window.addEventListener('pointercancel',done,{once:true})})}
function initDashboardStickyTimeline(){const wrap=document.querySelector('.portfolio-gantt-wrap'),axis=wrap?.querySelector('.portfolio-axis');if(!wrap||!axis)return;const shell=document.createElement('div');shell.className='portfolio-sticky-shell';const clone=axis.cloneNode(true);shell.appendChild(clone);document.body.appendChild(shell);const topbar=()=>document.querySelector('.topbar')?.getBoundingClientRect().height||64;const syncX=()=>{clone.style.transform='none';const timeHead=clone.querySelector('.portfolio-time-head');if(timeHead)timeHead.style.transform=`translateX(${-wrap.scrollLeft}px)`};const update=()=>{if(!document.body.contains(wrap)){cleanup();return}const r=wrap.getBoundingClientRect(),top=topbar(),h=axis.getBoundingClientRect().height;const show=r.top<top&&r.bottom>top+h+8;if(show){shell.style.display='block';shell.style.top=top+'px';shell.style.left=Math.max(0,r.left)+'px';shell.style.width=Math.max(0,Math.min(r.width,window.innerWidth-Math.max(0,r.left)))+'px';shell.style.height=h+'px';clone.style.width=axis.scrollWidth+'px';syncX()}else shell.style.display='none'};const onWindow=()=>update();const onWrap=()=>{syncX();if(shell.style.display!=='none')update()};window.addEventListener('scroll',onWindow,{passive:true});window.addEventListener('resize',onWindow);wrap.addEventListener('scroll',onWrap,{passive:true});function cleanup(){window.removeEventListener('scroll',onWindow);window.removeEventListener('resize',onWindow);wrap.removeEventListener('scroll',onWrap);shell.remove()}dashboardStickyCleanup=cleanup;update()}
