function responsibilityFields(list){list=Array.isArray(list)?list:[];return list.map((r,i)=>`<div class="form-grid" style="margin-bottom:8px"><div class="ff"><label>Responsible Unit</label><input value="${esc(r.unit)}" disabled></div><div class="ff"><label>PIC Name</label><input class="respPic" data-unit="${esc(r.unit)}" value="${esc(r.pic||'')}"></div></div>`).join('')||'<div class="small">No unit assigned in Key Milestone Master.</div>'}
function refreshResponsibilityFields(key){const units=ms(key).units;document.getElementById('respFields').innerHTML=responsibilityFields(units.map(u=>({unit:u,pic:''})))}
