function closeModal(){document.getElementById('modal').classList.add('hidden')}
function startPresentation(id){presentProjectIds=[id];presentIndex=0;page='presentation';render()}
function renderPresentation(){if(!presentProjectIds.length)presentProjectIds=state.projects.map(p=>p.id);const p=project(presentProjectIds[presentIndex]||state.selectedProjectId);if(!p)return'<div class="page"><div class="empty">No project to present.</div></div>';const inprog=(p.activities||[]).filter(a=>['InProgress','AtRisk','Delayed','OnHold'].includes(a.status));const next=(p.activities||[]).flatMap(a=>(a.nextSteps||[]).filter(s=>s.status!=='Completed').map(s=>({a,s}))).sort((x,y)=>dateVal(x.s.due)-dateVal(y.s.due)).slice(0,5);const recent=completedRecent(p).slice(0,4);return`<div class="present-shell"><div class="present-controls" style="max-width:1500px;margin:0 auto 10px;display:flex;gap:8px;color:white;align-items:center"><button class="btn" onclick="presentIndex=Math.max(0,presentIndex-1);render()">← Previous</button><button class="btn" onclick="presentIndex=Math.min(presentProjectIds.length-1,presentIndex+1);render()">Next →</button><span>${presentIndex+1} / ${presentProjectIds.length}</span><span style="margin-left:auto"></span><button class="btn" onclick="window.print()">Print / PDF</button><button class="btn primary" onclick="document.documentElement.requestFullscreen?.()">Full Screen</button></div><section class="slide"><div class="slide-head"><div><div class="slide-title">${esc(p.name)}</div><div class="sub">${esc(p.code)} · ${esc(p.eventType)} · ${esc(p.division)} / ${esc(p.department)}</div></div><div>${statusPill(projectStatus(p))}</div></div><div class="slide-body"><div class="slide-left"><div class="metric-row"><div class="slide-metric"><span>Progress</span><b>${progress(p)}%</b></div><div class="slide-metric"><span>Owner</span><b style="font-size:14px">${esc(p.owner)}</b></div><div class="slide-metric"><span>Upcoming 14D</span><b>${upcomingActivities(p,14).length}</b></div><div class="slide-metric"><span>Overdue</span><b class="${overdueSteps(p).length?'danger-text':''}">${overdueSteps(p).length}</b></div></div><div class="slide-card"><h3>Weekly Update / Executive Summary</h3><div>${esc(p.weeklyUpdate||p.summary||'No update entered.')}</div></div><div class="slide-card" style="flex:1"><h3>Current Focus / In Progress</h3>${inprog.slice(0,6).map(a=>`<div class="bullet"><span class="dot" style="background:${ms(a.key).color}"></span><div><b>${esc(a.key)} · ${esc(a.label||ms(a.key).name)}</b> ${statusPill(a.status)}<div class="small">${esc(workstreamOf(a))} → ${esc(taskOf(a))} → ${esc(a.subTask||'Main')} · ${esc(a.plannedStart)} → ${esc(a.plannedEnd)}</div></div></div>`).join('')||'<div class="small">No active milestone.</div>'}</div><div class="slide-card"><h3>Recently Completed</h3>${recent.map(a=>`<div class="bullet"><span class="dot" style="background:${ms(a.key).color}"></span><div><b>${esc(a.key)} · ${esc(a.label||ms(a.key).name)}</b><div class="small">Completed ${esc(a.actualEnd||a.plannedEnd)}</div></div></div>`).join('')||'<div class="small">No recent completion.</div>'}</div></div><div class="slide-right"><div class="slide-card"><h3>Next Steps</h3>${next.map(x=>`<div class="bullet"><span class="dot"></span><div><b>${esc(x.s.text)}</b><div class="small">${esc(x.a.key)} · Due ${esc(x.s.due)} · ${esc(x.s.status)}</div></div></div>`).join('')||'<div class="small">No open next steps.</div>'}</div><div class="slide-card"><h3>Risk / Issue</h3><div>${esc(p.risk||'No critical risk recorded.')}</div></div><div class="slide-card"><h3>Decision / Support Needed</h3><div>${esc(p.decision||'No decision required.')}</div></div><div class="slide-card" style="flex:1"><h3>Key Milestones</h3>${(p.activities||[]).slice().sort((a,b)=>dateVal(a.plannedEnd)-dateVal(b.plannedEnd)).slice(-7).map(a=>`<div style="display:grid;grid-template-columns:52px 1fr 80px;gap:8px;padding:6px 0;border-bottom:1px solid #edf1f5"><span class="code" style="background:${ms(a.key).color};padding:3px 5px">${esc(a.key)}</span><span>${esc(a.label||ms(a.key).name)}</span><span class="small">${esc(a.plannedEnd)}</span></div>`).join('')}</div></div></div><div class="slide-foot"><span>Range Operation Platform · Control Tower v2.0</span><span>Updated ${new Date().toLocaleString()}</span></div></section></div>`}
function masterDragHandle(){return `<span class="master-drag-handle" title="Drag to reorder" aria-hidden="true">☰</span>`}
function renderMaster(){const workstreams=state.masters.workstreams||[],milestones=state.masters.milestones||[],units=state.masters.units||[];return`<div class="page"><div class="page-head"><div><h1>Master Data</h1><div class="sub">Drag any row up/down to change display order. Workstream and Milestone order is used by Detail Plan dropdowns.</div></div></div><div class="master-grid"><div class="card master-list"><div class="section-title">Workstream Master <button class="btn sm primary" style="float:right" onclick="addMasterWorkstream()">+</button></div>${workstreams.map((t,i)=>`<div class="master-item master-draggable" draggable="true" data-master-type="workstreams" data-master-index="${i}"><span class="master-main">${masterDragHandle()}<span>${i+1}. ${esc(t)}</span></span><span><button class="btn sm" onclick="moveItem('workstreams',${i},-1)">↑</button> <button class="btn sm" onclick="moveItem('workstreams',${i},1)">↓</button> <button class="btn sm danger" onclick="requestDeleteMaster('workstreams',${i})">×</button></span></div>`).join('')}</div><div class="card master-list"><div class="section-title">Key Milestone Master <button class="btn sm primary" style="float:right" onclick="addMilestoneMaster()">+</button></div>${milestones.map((m,i)=>`<div class="master-item master-draggable" draggable="true" data-master-type="milestones" data-master-index="${i}"><span class="master-main">${masterDragHandle()}<span><i class="color-dot" style="background:${m.color}"></i><b>${esc(m.key)}</b> · ${esc(m.name)}<div class="small">${esc(m.kind||'Milestone')}${m.isLiveDefault?' · Live driver':''} · ${esc((m.units||[]).join(' / '))}</div></span></span><span><button class="btn sm" onclick="moveItem('milestones',${i},-1)">↑</button> <button class="btn sm" onclick="moveItem('milestones',${i},1)">↓</button> <button class="btn sm" onclick="editMilestoneMaster(${i})">Edit</button></span></div>`).join('')}</div><div class="card master-list"><div class="section-title">Responsible Unit Master <button class="btn sm primary" style="float:right" onclick="addUnitMaster()">+</button></div>${units.map((u,i)=>`<div class="master-item master-draggable" draggable="true" data-master-type="units" data-master-index="${i}"><span class="master-main">${masterDragHandle()}<span>${i+1}. ${esc(u)}</span></span><span><button class="btn sm" onclick="moveItem('units',${i},-1)">↑</button> <button class="btn sm" onclick="moveItem('units',${i},1)">↓</button> <button class="btn sm danger" onclick="requestDeleteMaster('units',${i})">×</button></span></div>`).join('')}</div></div></div>`}
let masterDragState=null;
function initMasterDragInteractions(){const rows=[...document.querySelectorAll('.master-draggable[data-master-type]')];rows.forEach(row=>{row.addEventListener('dragstart',e=>{if(e.target.closest('button,input,select,textarea')){e.preventDefault();return}masterDragState={type:row.dataset.masterType,index:Number(row.dataset.masterIndex)};row.classList.add('dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',`${masterDragState.type}:${masterDragState.index}`)}});row.addEventListener('dragend',()=>{row.classList.remove('dragging');document.querySelectorAll('.master-draggable.drag-over').forEach(x=>x.classList.remove('drag-over'));masterDragState=null});row.addEventListener('dragover',e=>{if(!masterDragState||masterDragState.type!==row.dataset.masterType)return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';document.querySelectorAll('.master-draggable.drag-over').forEach(x=>x.classList.remove('drag-over'));row.classList.add('drag-over')});row.addEventListener('dragleave',()=>row.classList.remove('drag-over'));row.addEventListener('drop',e=>{if(!masterDragState||masterDragState.type!==row.dataset.masterType)return;e.preventDefault();const type=masterDragState.type,from=masterDragState.index,to=Number(row.dataset.masterIndex),arr=state.masters[type];if(!Array.isArray(arr)||from===to)return;const [item]=arr.splice(from,1);arr.splice(to,0,item);save();render()})})}
function moveItem(type,i,d){const a=state.masters[type],j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];save();render()}
function masterDeleteLabel(type,i){if(type==='milestones'){const m=state.masters.milestones?.[i];return m?`${m.key} · ${m.name}`:'Milestone'}const value=state.masters[type]?.[i];return String(value||type)}
function masterUsagePath(a){return [workstreamOf(a),taskOf(a),a.subTask||'',a.key||''].filter(Boolean).join(' → ')}
function collectMasterUsages(type,i){
  const uses=[];
  if(type==='workstreams'){
    const value=state.masters.workstreams?.[i];
    if(!value)return uses;
    (state.projects||[]).forEach(p=>{
      (p.activities||[]).forEach(a=>{
        if(workstreamOf(a)===value){
          uses.push({source:'Plan Item',project:`${p.code||''}${p.code?' · ':''}${p.name||''}`,path:masterUsagePath(a),detail:`${a.activityType||'Activity'} · ${a.plannedStart||'—'} → ${a.plannedEnd||a.plannedStart||'—'}`});
        }
      });
    });
  }else if(type==='milestones'){
    const m=state.masters.milestones?.[i];
    if(!m)return uses;
    (state.projects||[]).forEach(p=>{
      (p.activities||[]).forEach(a=>{
        if(a.key===m.key){
          uses.push({source:'Plan Item',project:`${p.code||''}${p.code?' · ':''}${p.name||''}`,path:masterUsagePath(a),detail:`${a.activityType||'Activity'} · ${a.plannedStart||'—'} → ${a.plannedEnd||a.plannedStart||'—'}`});
        }
      });
    });
  }else if(type==='units'){
    const value=state.masters.units?.[i];
    if(!value)return uses;
    (state.masters.milestones||[]).forEach(m=>{
      if((m.units||[]).includes(value)){
        uses.push({source:'Milestone Master',project:'—',path:`${m.key} · ${m.name}`,detail:'Default Responsible Unit'});
      }
    });
    (state.projects||[]).forEach(p=>{
      (p.activities||[]).forEach(a=>{
        const matched=(a.responsibilities||[]).filter(r=>r.unit===value);
        matched.forEach(r=>{
          uses.push({source:'Plan Item PIC',project:`${p.code||''}${p.code?' · ':''}${p.name||''}`,path:masterUsagePath(a),detail:r.pic?`PIC: ${r.pic}`:'Responsible Unit'});
        });
      });
    });
  }
  return uses;
}
function masterUsageRows(usages){return usages.map((u,n)=>`<tr><td>${n+1}</td><td><b>${esc(u.source)}</b></td><td>${esc(u.project)}</td><td>${esc(u.path)}</td><td>${esc(u.detail)}</td></tr>`).join('')}
function masterReplacementOptions(type,i){
  const arr=state.masters[type]||[];
  return arr.map((item,index)=>({item,index})).filter(x=>x.index!==i).map(x=>({
    index:x.index,
    label:type==='milestones'?`${x.item.key} · ${x.item.name}`:String(x.item||'')
  }));
}
function masterReplacementTypeLabel(type){return type==='milestones'?'Milestone':type==='workstreams'?'Workstream':'Responsible Unit'}
function replaceMasterReferences(type,fromIndex,toIndex){
  const arr=state.masters[type]||[],from=arr[fromIndex],to=arr[toIndex];
  if(!from||!to||fromIndex===toIndex)return 0;
  let changed=0;
  if(type==='workstreams'){
    (state.projects||[]).forEach(p=>(p.activities||[]).forEach(a=>{
      if(workstreamOf(a)===from){a.workstream=to;changed++}
    }));
  }else if(type==='milestones'){
    (state.projects||[]).forEach(p=>(p.activities||[]).forEach(a=>{
      if(a.key===from.key){a.key=to.key;changed++}
    }));
  }else if(type==='units'){
    (state.masters.milestones||[]).forEach(m=>{
      if((m.units||[]).includes(from)){
        m.units=[...new Set((m.units||[]).map(u=>u===from?to:u))];changed++
      }
    });
    (state.projects||[]).forEach(p=>(p.activities||[]).forEach(a=>{
      if(!(a.responsibilities||[]).some(r=>r.unit===from))return;
      const merged=[];
      (a.responsibilities||[]).forEach(r=>{
        const unit=r.unit===from?to:r.unit;
        const existing=merged.find(x=>x.unit===unit);
        if(existing){
          const pics=[existing.pic,r.pic].map(x=>String(x||'').trim()).filter(Boolean);
          existing.pic=[...new Set(pics)].join(' / ');
        }else merged.push({...r,unit});
      });
      a.responsibilities=merged;changed++
    }));
  }
  return changed;
}
function requestDeleteMaster(type,i){
  const label=masterDeleteLabel(type,i),usages=collectMasterUsages(type,i),used=usages.length>0,replacements=masterReplacementOptions(type,i),typeLabel=masterReplacementTypeLabel(type);
  const replacementBlock=used?`<div class="master-replace-box"><div class="section-title">Replace before delete</div>${replacements.length?`<div class="ff"><label>Change all references to another ${esc(typeLabel)}</label><select id="masterReplacementIndex">${replacements.map(x=>`<option value="${x.index}">${esc(x.label)}</option>`).join('')}</select></div><div class="small">The current ${esc(typeLabel)} reference will be replaced in all locations listed below. Project dates, status, PIC names, Task and Sub-Task values are preserved.</div>`:`<div class="master-usage-warning"><b>No replacement available.</b> Add another ${esc(typeLabel)} in Master Data before deleting this item.</div>`}</div>`:'';
  showModal(`<div class="modal-head"><h2>${used?'Replace & Delete Master Data':'Delete Master Data'}</h2><button class="btn sm" onclick="closeModal()">×</button></div><div class="modal-body"><div class="section-title">${esc(label)}</div>${used?`<div class="master-usage-warning">This Master Data is currently referenced in <b>${usages.length}</b> location${usages.length===1?'':'s'}. Review the usage, choose a replacement, then delete the old Master.</div>${replacementBlock}<div class="master-usage-table"><table class="table"><thead><tr><th>#</th><th>Used As</th><th>Project</th><th>Location</th><th>Detail</th></tr></thead><tbody>${masterUsageRows(usages)}</tbody></table></div>`:`<div class="small">No current references were found for this Master Data. It can be deleted safely.</div>`}</div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancel</button>${used?(replacements.length?`<button class="btn danger" onclick="replaceAndDeleteMaster('${esc(type)}',${i})">Replace References & Delete</button>`:''):`<button class="btn danger" onclick="confirmDeleteMaster('${esc(type)}',${i})">Delete</button>`}</div>`)
}
function replaceAndDeleteMaster(type,i){
  const select=document.getElementById('masterReplacementIndex'),toIndex=Number(select?.value);
  const arr=state.masters[type]||[],fromLabel=masterDeleteLabel(type,i),to=arr[toIndex];
  if(!Number.isInteger(toIndex)||!to||toIndex===i)return alert('Please select a valid replacement.');
  const toLabel=type==='milestones'?`${to.key} · ${to.name}`:String(to);
  const usages=collectMasterUsages(type,i);
  if(!confirm(`Replace ${usages.length} reference${usages.length===1?'':'s'} from “${fromLabel}” to “${toLabel}”, then permanently delete the old Master?`))return;
  replaceMasterReferences(type,i,toIndex);
  state.masters[type].splice(i,1);
  save();closeModal();render();
}
function confirmDeleteMaster(type,i){if(!state.masters[type]?.[i])return closeModal();state.masters[type].splice(i,1);save();closeModal();render()}
function deleteMaster(type,i){requestDeleteMaster(type,i)}
function addMasterWorkstream(){const x=prompt('Workstream name');if(x&&!state.masters.workstreams.includes(x.trim())){state.masters.workstreams.push(x.trim());save();render()}}
function addUnitMaster(){const x=prompt('Responsible Unit name');if(x&&!state.masters.units.includes(x)){state.masters.units.push(x.trim());save();render()}}
function addMilestoneMaster(){showMilestoneModal(-1)}function editMilestoneMaster(i){showMilestoneModal(i)}
